<script setup>
import {computed} from 'vue';import {FontAwesomeIcon} from '@fortawesome/vue-fontawesome';import {faGoogle,faFacebookF} from '@fortawesome/free-brands-svg-icons';
import AccountIcon from './AccountIcon.vue';import AccountResource from './AccountResource.vue';
const props=defineProps({addresses:Object,profile:Object});defineEmits(['retry-addresses','retry-profile']);
const address=computed(()=>props.addresses.data?.find(a=>a.isDefault));
const text=a=>[a.addressDetail,a.wardName,a.districtName,a.provinceName].filter(Boolean).join(', ');
</script>
<template><div class="bm-buyer-account-pair"><section class="bm-buyer-account-card"><h2><AccountIcon name="pin"/>Địa chỉ mặc định</h2><AccountResource :resource="addresses" label="địa chỉ" @retry="$emit('retry-addresses')"><template v-if="address"><div class="bm-buyer-account-address"><div><strong>{{ address.recipientName }} · {{ address.phone }}</strong><span class="bm-buyer-account-badge">Mặc định</span></div><p><AccountIcon name="home"/>{{ text(address) }}</p></div><RouterLink class="bm-buyer-account-text-link" to="/profile?section=addresses"><AccountIcon name="edit"/>Chỉnh sửa</RouterLink></template><template v-else><p>{{ addresses.data.length?'Bạn chưa chọn địa chỉ mặc định.':'Bạn chưa thêm địa chỉ nhận hàng.' }}</p><RouterLink class="button button-outline" to="/profile?section=addresses">{{ addresses.data.length?'Quản lý địa chỉ':'Thêm địa chỉ nhận hàng' }}</RouterLink></template></AccountResource></section><section class="bm-buyer-account-card"><h2><AccountIcon name="shield"/>Bảo mật tài khoản</h2><dl class="bm-buyer-account-security"><div><dt><AccountIcon name="mail"/>Email</dt><dd>{{ profile.data?profile.data.emailVerified?'Đã xác thực':'Chưa xác thực':profile.loading?'Đang tải…':'Chưa xác định' }}</dd></div><div><dt><AccountIcon name="lock"/>Mật khẩu</dt><dd>Quản lý trong bảo mật</dd></div><div><dt><FontAwesomeIcon :icon="faGoogle"/>Google</dt><dd>Chưa có thông tin liên kết</dd></div><div><dt><FontAwesomeIcon :icon="faFacebookF"/>Facebook</dt><dd>Chưa có thông tin liên kết</dd></div></dl><RouterLink class="button button-primary bm-buyer-account-security-cta" to="/profile?section=security"><AccountIcon name="shield"/>Quản lý bảo mật</RouterLink></section></div></template>
